SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0430000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 43, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "43", "printedPageNumber": 43, "pdfPageNumber": 426, "sequenceIndex": 33, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0430000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part I (b)—Warning on Discard of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "his time in the mosque. Allah shall keep him in comfort and shall make him cross the Siraat with great ease. Surely Allah is pleased with such a person.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Mas''ood (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"The masaajid are the Houses of Allah, and people coming therein are His visitors. When everybody treats his visitors kindly, why should Allah not be kind to His guests?\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"Allah loves the person who is attached to the musjid.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"When a dead person is laid in the grave, even before the people present at his burial clear off, Munkar and Nakeer visit him. Then, if the person is a Mo''min, his good practices encircle him; salaat comes close to his head, Zakaat to his right, Fast to his left, and the remaining good deeds towards his feet, so that none can approach him. Even the angels do the necessary questioning while standing at a distance.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430500-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "One of the companions reports that, when the inmates of the Prophet''s house were hard-pressed in any way, he would enjoin salaat on them and recite the following verse:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430600-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ وَاصْطَبِرْ عَلَيْهَا لَا نَسْأَلُكَ رِزْقًا نَحْنُ نَرْزُقُكَ وَالْعَاقِبَةُ لِلتَّقْوَى", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430700-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"And enjoin salaat upon thy people and be constant therein. We ask not of thee a provision, We provide for thee. And the Hereafter is for the righteousness.\" (XX: 132).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}, {"id": "f0430800-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 8, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Asma (Radhiyallaho anha) narrates that she heard the Prophet (Sallallaho alaihe wasallam) saying, \"All the people will be gathered together on the Day of Judgement and they will all hear the voice of the announcing angel. He will say, ''where are those who glorified Allah in ease and adversity?'' A group will rise up and enter Paradise without reckoning. It will then be announced, ''where are those who forsook their beds and spent their nights in worship?'' Another group will rise up and enter Paradise without reckoning. The angel will again announce, ''where", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 43"}]}'::jsonb);